  "e079": {"o": "pair", "keep": "用国内福利与海外援助的关系改写时，保留题干的推理前提，即无法帮到所有人。立场须说明国内基本服务是否优先，以及这一优先顺序给定向海外援助留下什么空间。", "p": "conditional", "a": ["gov-funded-readiness", "public"], "b": ["gov-match-aid", "public"], "ex": "service", "risk": "quality", "reply": "safeguard"},
  "e081": {"o": "nominal", "keep": "用纳税义务概括话题后，要把原主张中的 all 和不缴税保留下来。立场应明确反对保留全部收入，并说明公平分担公共服务费用的含义。", "p": "no", "a": ["gov-funded-readiness", "public"], "b": ["gov-basic-continuity", "access"], "ex": "process", "risk": "resources", "reply": "safeguard"},
  "e082": {"o": "pair", "keep": "把国际大赛的运动员训练经费与鼓励儿童从小参与运动并列。立场要回答同一笔钱怎样分配才更好，并说明给儿童较多经费是否意味着终止全部精英训练。", "p": "conditional", "a": ["gov-entry-cost", "access"], "b": ["gov-usable-spaces", "access"], "ex": "decision", "risk": "resources", "reply": "phase"},
  "e085": {"o": "pair", "keep": "保留大城市旧建筑的修复开支，以及把这笔钱转投新住房和道路的提议。立场要分别写出什么旧楼仍值得修，何种具体短缺使新建设施应优先。", "p": "conditional", "a": ["gov-usable-spaces", "public"], "b": ["gov-urgent-gaps", "cost"], "ex": "compare", "risk": "resources", "reply": "safeguard"},
